// Für neue Tests request_id ändern. Gleiche IDs werden nicht erneut verarbeitet.
return [{json: {
  request_id: 'SUP-TEST-003',
  customer_id: 'K001',
  subject: 'Passwort vergessen',
  message: 'Wie kann ich mein Passwort zurücksetzen?'
}}];

const current = $input.first().json;
const raw = $input.first().json;
const p = raw.body !== undefined ? raw.body : raw;
const errors = [];
if (!p || typeof p !== 'object' || Array.isArray(p)) {
  return [{json: {valid: false, errors: ['BODY_MUST_BE_OBJECT'],
    status: 'rejected', decision: 'reject'}}];
}
const read = key => typeof p[key] === 'string' ? p[key].trim() : '';
const request = {
  request_id: read('request_id'),
  submitted_customer_id: read('customer_id') || null,
  subject: read('subject'), message: read('message')
};
if (!/^[A-Za-z0-9_-]{1,80}$/.test(request.request_id)) errors.push('REQUEST_ID_INVALID');
if (!request.subject || request.subject.length > 200) errors.push('SUBJECT_INVALID');
if (!request.message || request.message.length > 8000) errors.push('MESSAGE_INVALID');
if ((request.submitted_customer_id || '').length > 80) errors.push('CUSTOMER_ID_INVALID');
if ([request.subject, request.message, request.submitted_customer_id || ''].some(s => s.includes('\u0000'))) errors.push('NUL_CHARACTER');
// Nur benötigte Nutzdaten speichern, niemals Webhook-Header oder Auth-Geheimnisse.
request.input_payload = {
  request_id: request.request_id, customer_id: request.submitted_customer_id,
  subject: request.subject, message: request.message
};
return [{json: {valid: errors.length === 0, errors, request}}];

const current = $input.first().json;
return [{json: {request_id: current.request?.request_id || null,
  status: 'rejected', decision: 'reject', reason_codes: current.errors,
  persisted: false}}];

const current = $input.first().json;
return [{json: {request_id: current.request.request_id, status: 'duplicate',
  decision: null, processed: false,
  message: 'Anfrage-ID bereits vorhanden. Keine erneute KI-Verarbeitung.'}}];
